 function renderStrategy(s){const root=$('structured-strategy');root.replaceChildren();const objective=$('strategy-objective').value,m=metrics(s.rows);if(!s.rows.length){root.textContent='Select data to create a recommendation.';return;}if(objective==='Increase engagement'&&m.engagementRate===null){root.textContent='Engagement data is unavailable. Import an engagements column before making an engagement recommendation.';return;}const parts=[['Finding',`${objective==='Increase engagement'?'Observed engagement rate '+number(m.engagementRate)+'%. ':''}${objective}: ${s.rows.length} selected observations; CPA ${dollars(m.cpa)}, ROAS ${number(m.roas)}×, conversion rate ${number(m.cvr)}%.`],['Supporting evidence',`Spend ${dollars(m.spend)}, clicks ${number(m.clicks)}, conversions ${number(m.conversions)}.`],['Why it matters','Efficiency and conversion quality determine whether additional spend is worth testing.'],['Proposed action',objective==='Improve campaign reach'?'Collect unique-reach and frequency data; impressions alone do not establish reach.':'Test one creative message or audience segment against a comparable control.'],['Hypothesis','A clearer benefit and stronger audience fit may improve qualified conversions. This is a testable hypothesis, not a measured cause.'],['KPI',objective==='Increase ROAS'?'ROAS with contribution margin guardrail':objective==='Increase engagement'?'Engagement rate with conversion-quality guardrail':'CPA and conversion rate with lead-quality guardrails'],['Validation method','Predefine success and sample requirements. Use a holdout where feasible and evaluate the complete test window.'],['Limitations','No causal evidence, attribution audit, or unique customer-quality measure is available.']];const dl=el('dl','','recommendation');parts.forEach(([a,b])=>dl.append(el('dt',a),el('dd',b)));root.append(dl)}
