 async function copy(text,id){try{await navigator.clipboard.writeText(text);status(id,'Copied.')}catch{status(id,'Clipboard unavailable. Select and copy the visible text manually.')}}
 $('chat-form').onsubmit=async event=>{event.preventDefault();const question=$('chat-question').value.trim();if(!question)return;const s=context(),ctx=s.evidence,local=answerQuestion(question,ctx),id=++requestId;status('chat-status','Calculating from selected records…');$('chat-question').value='';if(!$('chat-gemini').checked){addChat(question,local,ctx,'Calculated locally');status('chat-status','Ready. Follow up with a question about CPA, ROAS, changes, or missing information.');return;}
 const endpoint=config.apiBase||$('endpoint').value;if(!endpoint){addChat(question,local,ctx,'Calculated locally · Gemini not configured');status('chat-status','Owner must configure config.js and deploy the Worker for Gemini. Local analysis is ready.');return;}
 if(!confirm('Send selected campaign aggregates, filter labels, this question, and up to four recent messages to your Worker and Google Gemini? No raw CSV is sent. Use nonconfidential data only.')){addChat(question,local,ctx,'Calculated locally');status('chat-status','Gemini request cancelled.');return;}
 status('chat-status','Requesting Gemini interpretation…');activeRequest=new AbortController();const timeout=setTimeout(()=>activeRequest.abort(),config.assistantTimeout);const submit=$('chat-form').querySelector('[type=submit]');submit.disabled=true;try{const u=new URL(endpoint);if(u.protocol!=='https:'||!u.hostname.endsWith('.workers.dev')||u.username||u.password||u.search||u.hash)throw Error('Invalid configured Worker URL');const result=await fetch(u.origin+'/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({summary:ctx.channels.map(({channel,spend,revenue,impressions,clicks,conversions})=>({channel,spend,revenue,impressions,clicks,conversions})),context:ctx,question,history:messages.slice(-4).map(m=>({question:m.question.slice(0,500),answer:m.answer.slice(0,1500)}))}),signal:activeRequest.signal});const body=await result.json();if(!result.ok)throw Error(body.error||'AI service unavailable');if(typeof body.text!=='string'||!body.text.trim())throw Error('Empty response');if(id!==requestId)return;addChat(question,local+'\n\nGemini interpretation (review for accuracy):\n'+body.text,ctx,'Calculated evidence + Gemini');status('chat-status','Response received. AI interpretation may be imperfect; check the attached evidence.')}catch(error){if(id===requestId){addChat(question,local,ctx,'Calculated fallback');status('chat-status',`Gemini unavailable: ${error.name==='AbortError'?'request timed out':error.message}. Local answer preserved. Try again manually.`)}}finally{clearTimeout(timeout);submit.disabled=false;activeRequest=null}}
