 $('experiment-form').onsubmit=event=>{event.preventDefault();const s=context(),experimentRows=s.rows.filter(r=>r.channel===$('experiment-channel').value),m=metrics(experimentRows);if(!experimentRows.length){status('experiment-status','Select observations for the chosen experiment channel before recording a baseline.');return;}const kpi=$('experiment-kpi').value,key={CPA:'cpa',ROAS:'roas','Conversion rate':'cvr',CTR:'ctr'}[kpi],p={name:$('experiment-name').value.trim(),objective:$('strategy-objective').value,hypothesis:$('experiment-hypothesis').value.trim(),action:$('experiment-action').value,kpi,baseline:number(m[key]),success:$('experiment-success').value,status:$('experiment-state').value,notes:$('experiment-notes').value,impact:Number($('ice-impact').value),confidence:Number($('ice-confidence').value),effort:Number($('ice-effort').value),channel:$('experiment-channel').value,budget:$('experiment-budget').value,days:$('experiment-days').value,filters:s.filters};if(!p.name||!p.hypothesis||ice(p.impact,p.confidence,p.effort)===null){status('experiment-status','Enter a name, hypothesis, and valid 1–10 priority scores.');return;}if(['In progress','Completed'].includes(p.status)&&!p.success.trim()){status('experiment-status','Set a success criterion before marking an experiment in progress or completed.');return;}if(editing!==null){experiments[editing]=p;editing=null}else{if(experiments.length>=50){status('experiment-status','Maximum 50 saved experiments.');return;}experiments.push(p)}const saved=safeStore('mi-experiments-v2',experiments);status('experiment-status',saved?'Experiment saved in this browser.':'Saved for this tab only; export a copy.');$('download-experiment').disabled=false;renderExperiments()};$('download-experiment').onclick=()=>api.download('experiments.json',JSON.stringify(experiments,null,2),'application/json');
